// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "@openzeppelin/contracts/utils/Context.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "luk1529_solidity/contracts/token/ERC721User.sol";
import "luk1529_solidity/contracts/fee/FeeTakersERC20.sol";
import "luk1529_solidity/contracts/utils/Random.sol";
import "./AttributeManager.sol";

contract Tamagotchi is Ownable, ERC721User, FeeTakers, Random("toomoogoochoo") {
    using Strings for int;
    constructor(IERC20 Coink, IERC721 Piggies, AttributeManager attributeManager, uint revivalPrice, DefaultAttribute[] memory defaultAttributes, PowerupParams[] memory powerupParams, RandomEventParams[] memory randomEventParams, PurchaseableEventParams[] memory purchaseableEventParams) ERC20User(Coink) ERC721User(Piggies) {
        _attributeManager = attributeManager;
        for(uint i; i < powerupParams.length; i ++) {
            _powerups.push();
            _powerups[i].params = powerupParams[i];
        }
        for(uint i; i < defaultAttributes.length; i ++) {
            _defaultAttributes.push(defaultAttributes[i]);
        }
        for(uint i; i < randomEventParams.length; i ++) {
            _randomEvents.push();
            _randomEvents[i].params = randomEventParams[i];
        }
        for (uint i; i < purchaseableEventParams.length; i ++) {
            _purchaseableEvents.push();
            _purchaseableEvents[i].params = purchaseableEventParams[i];
        }
        _setRevivalPrice(revivalPrice);
    }

    struct DefaultAttribute {
        string attributeName;
        int value;
        int thresholdValue;
        int decay;
    } 

    struct PowerupParams {
        string name;
        bool occupy;
        uint price;
        string attributeName;
        int decay;
        uint length;
        uint cooldown;
    }

    struct Powerup {
        PowerupParams params;
        Requirement[] requirements;
        mapping(uint => uint) lastUsed;
    }

    struct RandomEvent {
        RandomEventParams params;
        Requirement[] requirements;
    }

    struct RandomEventParams {
        string name;
        uint percentageChance;
        string attributeName;
        int effect;
    }

    struct PurchaseableEventParams {
        string name;
        uint price;
        string attributeName;
        int effect;
        uint cooldown;
    }

    struct PurchaseableEvent {
        PurchaseableEventParams params;
        Requirement[] requirements;
        mapping(uint => uint) lastUsed;
    }

    struct Requirement {
        string attributeName;
        int value;
    }

    struct OccupiedData {
        string name;
        uint occupiedUntil;
    }

    uint _revivalPrice;
    mapping(uint => bool) _imported;
    mapping(uint => OccupiedData) _occupiedUntil;

    AttributeManager _attributeManager;
    DefaultAttribute[] _defaultAttributes;
    Powerup[] _powerups;
    RandomEvent[] _randomEvents;
    PurchaseableEvent[] _purchaseableEvents;
    

    //end user stuff
    function isImported(uint pigId) public view returns(bool) {
        return _isImported(pigId);
    }
    function isDead(uint pigId) public view returns(bool) {
        return _isDead(pigId);
    }
    function occupiedUntil(uint pigId) public view returns(OccupiedData memory) {
        return _occupiedUntil[pigId];
    }
    function importPig(uint pigId) public onlyPigOwner(pigId) {
        require(!_isImported(pigId), "Pig already imported.");
        _applyDefaultAttributesToPig(pigId);
        _markImported(pigId);
    }
    function getRevivalPrice() public view returns(uint) {
        return _revivalPrice;
    }
    function revivePig(uint pigId) public onlyPigOwner(pigId) {
        uint toPay = _revivalPrice;
        _coinkContract().transferFrom(_msgSender(), address(this), toPay);
        _distributeFee(toPay);
        _applyDefaultAttributesToPig(pigId);
    }
    function getAttributeList() public view returns(DefaultAttribute[] memory attributes) {
        return _defaultAttributes;
    }
    function getPowerups() public view returns(PowerupParams[] memory powerups) {
        powerups = new PowerupParams[](_powerups.length);
        for(uint i; i < _powerups.length; i ++) {
            powerups[i] = _powerups[i].params;
        }
    }
    function getRequirementsOfPowerup(uint index) public view returns(Requirement[] memory) {
        return _powerups[index].requirements;
    }
    function getRandomEvents() public view returns(RandomEvent[] memory) {
        return _randomEvents;
    }
    function getPurchaseableEvents() public view returns(PurchaseableEventParams[] memory events) {
        events = new PurchaseableEventParams[](_purchaseableEvents.length);
        for(uint i; i < _purchaseableEvents.length; i ++) {
            events[i] = _purchaseableEvents[i].params;
        }
    }
    function getRequirementsOfPurchaseableEvent(uint index) public view returns(Requirement[] memory) {
        return _purchaseableEvents[index].requirements;
    }
    function getCooldownEndsAtForPowerupOfPig(uint pigId, uint index) public view returns(uint) {
        return _powerups[index].lastUsed[pigId] + _powerups[index].params.cooldown;
    }
    function getCooldownEndsAtForPurchaseableEventOfPig(uint pigId, uint index) public view returns(uint) {
        return _purchaseableEvents[index].lastUsed[pigId] + _purchaseableEvents[index].params.cooldown;
    }



    //main
    function setNameOfPig(uint pigId, string calldata name) public onlyPigOwner(pigId) {
        _attributeManagerContract().setNameOfPig(pigId, name);
    }
    function buyPowerup(uint pigId, uint index) public onlyPigOwner(pigId) onlyNotDead(pigId) onlyNotOccupied(pigId) {
        _applyPowerup(_msgSender(), pigId, _powerups[index]);
        _applyRandomEventsToPig(pigId);
    }
    function buyEvent(uint pigId, uint index) public onlyPigOwner(pigId) onlyNotDead(pigId) onlyNotOccupied(pigId) {
        _applyEvent(_msgSender(), pigId, _purchaseableEvents[index]);
        _applyRandomEventsToPig(pigId);
    }
    
    

    //admin stuff
    function editPriceOfPowerup(uint index, uint price) public onlyOwner {
        _editPriceOfPowerup(_powerups[index], price);
    }
    function editCooldownOfPowerup(uint index, uint cooldown) public onlyOwner {
        _editCooldownOfPowerup(_powerups[index], cooldown);
    }
    function editDecayOfPowerup(uint index, int decay, uint length) public onlyOwner {
        _editDecayOfPowerup(_powerups[index], decay, length);
    }
    function editOccupyOfPowerup(uint index, bool occupy) public onlyOwner {
        _editOccupyOfPowerup(_powerups[index], occupy);
    }
    function setRequirementsOfPowerup(uint index, Requirement[] memory requirements) public onlyOwner {
        _setRequirementsOfPowerup(_powerups[index], requirements);
    }
    function editPriceOfPurchaseableEvent(uint index, uint price) public onlyOwner {
        _editPriceOfPurchaseableEvent(_purchaseableEvents[index], price);
    }
    function editCooldownOfPurchaseableEvent(uint index, uint cooldown) public onlyOwner {
        _editCooldownOfPurchaseableEvent(_purchaseableEvents[index], cooldown);
    }
    function editEffectOfPurchaseableEvent(uint index, int effect) public onlyOwner {
        _editEffectOfPurchaseableEvent(_purchaseableEvents[index], effect);
    }
    function setRequirementsOfPurchaseableEvent(uint index, Requirement[] memory requirements) public onlyOwner {
        _setRequirementsOfPurchaseableEvent(_purchaseableEvents[index], requirements);
    }
    function editDefaultAttributeValue(uint index, int value) public onlyOwner {
        _editDefaultAttributeValue(_defaultAttributes[index], value);
    }
    function editChanceOfRandomEvent(uint index, uint percentageChance) public onlyOwner {
        _editChanceOfRandomEvent(_randomEvents[index], percentageChance);
    }
    function editEffectOfRandomEvent(uint index, int effect) public onlyOwner {
        _editEffectOfRandomEvent(_randomEvents[index], effect);
    }
    function setRequirementsOfRandomEvent(uint index, Requirement[] memory requirements) public onlyOwner {
        _setRequirementsOfRandomEvent(_randomEvents[index], requirements);
    }
    function setRevivalPrice(uint revivalPrice) public onlyOwner {
        _setRevivalPrice(revivalPrice);
    }

    //internal stuff
    function _editCooldownOfPowerup(Powerup storage powerup, uint cooldown) private {
        powerup.params.cooldown = cooldown;
    }
    function _editDecayOfPowerup(Powerup storage powerup, int decay, uint length) private {
        powerup.params.decay = decay;
        powerup.params.length = length;
    }
    function _editPriceOfPowerup(Powerup storage powerup, uint price) private {
        powerup.params.price = price;
    }
    function _editOccupyOfPowerup(Powerup storage powerup, bool occupy) private {
        powerup.params.occupy = occupy;
    }
    function _setRequirementsOfPowerup(Powerup storage powerup, Requirement[] memory requirements) private {
        if(powerup.requirements.length > 0){
            delete powerup.requirements;
        }
        for(uint i; i < requirements.length; i ++) {
            powerup.requirements.push();
            powerup.requirements[i].attributeName = requirements[i].attributeName;
            powerup.requirements[i].value = requirements[i].value;
        }
    }
    function _editCooldownOfPurchaseableEvent(PurchaseableEvent storage purchaseableEvent, uint cooldown) private {
        purchaseableEvent.params.cooldown = cooldown;
    }
    function _editEffectOfPurchaseableEvent(PurchaseableEvent storage purchaseableEvent, int effect) private {
        purchaseableEvent.params.effect = effect;
    }
    function _editPriceOfPurchaseableEvent(PurchaseableEvent storage purchaseableEvent, uint price) private {
        purchaseableEvent.params.price = price;
    }
    function _setRequirementsOfPurchaseableEvent(PurchaseableEvent storage purchaseableEvent, Requirement[] memory requirements) private {
        if(purchaseableEvent.requirements.length > 0){
            delete purchaseableEvent.requirements;
        }
        for(uint i; i < requirements.length; i ++) {
            purchaseableEvent.requirements.push();
            purchaseableEvent.requirements[i].attributeName = requirements[i].attributeName;
            purchaseableEvent.requirements[i].value = requirements[i].value;
        }
    }
    function _editDefaultAttributeValue(DefaultAttribute storage defaultAttribute, int value) private {
        defaultAttribute.value = value;
    }
    function _editChanceOfRandomEvent(RandomEvent storage randomEvent, uint percentageChance) private {
        randomEvent.params.percentageChance = percentageChance;
    }
    function _editEffectOfRandomEvent(RandomEvent storage randomEvent, int effect) private {
        randomEvent.params.effect = effect;
    }
    function _setRequirementsOfRandomEvent(RandomEvent storage randomEvent, Requirement[] memory requirements) private {
        delete randomEvent.requirements;
        for(uint i; i < requirements.length; i ++) {
            randomEvent.requirements.push();
            randomEvent.requirements[i].attributeName = requirements[i].attributeName;
            randomEvent.requirements[i].value = requirements[i].value;
        }
    }
    function _setRevivalPrice(uint revivalPrice) private {
        _revivalPrice = revivalPrice;
    }

    function _applyPowerup(address player, uint pigId, Powerup storage powerup) private {
        _enforceRequirements(pigId, powerup.requirements);
        uint toPay = powerup.params.price;
        _coinkContract().transferFrom(player, address(this), toPay);
        _distributeFee(toPay);
        require(_blkNumber() > powerup.lastUsed[pigId] + powerup.params.cooldown, "Please wait for cooldown.");
        _attributeManagerContract().addBoostToAttributeOfPig(pigId, powerup.params.attributeName, powerup.params.name, powerup.params.decay, powerup.params.length);
        if(powerup.params.occupy) {
            _occupyFor(pigId, powerup.params.name, powerup.params.length);
        }
        powerup.lastUsed[pigId] = _blkNumber();
    }
    function _applyEvent(address player, uint pigId, PurchaseableEvent storage purchaseableEvent) private {
        _enforceRequirements(pigId, purchaseableEvent.requirements);
        uint toPay = purchaseableEvent.params.price;
        _coinkContract().transferFrom(player, address(this), toPay);
        _distributeFee(toPay);
        require(_blkNumber() > purchaseableEvent.lastUsed[pigId] + purchaseableEvent.params.cooldown, "Please wait for cooldown");
        _attributeManagerContract().eventToAttributeValueOfPig(pigId, purchaseableEvent.params.attributeName, purchaseableEvent.params.name, purchaseableEvent.params.effect);
        purchaseableEvent.lastUsed[pigId] = _blkNumber();
    }
    function _applyDefaultAttributesToPig(uint pigId) private {
        uint length = _defaultAttributes.length;
        for(uint i; i < length; i ++) {
            string memory attributeName = _defaultAttributes[i].attributeName;
            int value = _defaultAttributes[i].value;
            int decay = _defaultAttributes[i].decay;
            _attributeManagerContract().clearAttributeOfPig(pigId, attributeName);
            _attributeManagerContract().eventToAttributeValueOfPig(pigId, attributeName, "initialise", value);
            _attributeManagerContract().modifyDecayOfAttributeOfPig(pigId, attributeName, decay);
        }
    }
    function _applyRandomEventsToPig(uint pigId) private {
        uint length = _randomEvents.length;
        for(uint i; i < length; i ++) {
            RandomEvent storage randomEvent = _randomEvents[i];
            bool applied = _randomNumber(100) < randomEvent.params.percentageChance;
            bool requirementsMet = true;
            for(uint j = randomEvent.requirements.length; j < length; j ++) {
                bool requirementMet = _isRequirementMet(pigId, randomEvent.requirements[i]);
                if(!requirementMet) {
                    requirementsMet = false;
                    break;
                }
            }
            if (applied && requirementsMet) {
                _attributeManagerContract().eventToAttributeValueOfPig(pigId, randomEvent.params.attributeName, randomEvent.params.name, randomEvent.params.effect);
            }
        }
    }
    function _enforceRequirements(uint pigId, Requirement[] storage requirements) private view {
        uint length = requirements.length;
        for(uint i; i < length; i ++) {
            bool requirementMet = _isRequirementMet(pigId, requirements[i]);
            if(!requirementMet) {
                string memory errorMessage = string(abi.encodePacked(
                    "This action failed because",
                    " ",
                    requirements[i].attributeName,
                    " ",
                    "is too low."
                ));
                revert(errorMessage);
            }
        }
    }
    function _isRequirementMet(uint pigId, Requirement storage requirement) private view returns(bool) {
        string memory attributeName = requirement.attributeName;
        int requiredValue = requirement.value;
        int value = _attributeManagerContract().getAttributeValueOfPig(pigId, attributeName);
        return value >= requiredValue ? true : false;
    }
    function _occupyFor(uint pigId, string storage name, uint length) private {
        _occupiedUntil[pigId].occupiedUntil = _blkNumber() + length;
        _occupiedUntil[pigId].name = name;
    }
    function _markImported(uint pigId) private{
        _imported[pigId] = true;
    }
    function _isImported(uint pigId) private view returns(bool) {
        return _imported[pigId];
    }
    function _isDead(uint pigId) private view returns(bool dead) {
        for(uint i; i < _defaultAttributes.length; i ++) {
            string memory attributeName = _defaultAttributes[i].attributeName;
            int thresholdValue = _defaultAttributes[i].thresholdValue;
            int value = _attributeManagerContract().getAttributeValueOfPig(pigId, attributeName);
            if(value < thresholdValue) {
                return true;
            }
        }
    }

    function _blkNumber() private view returns(uint) {
        return block.number;
    }

    modifier onlyPigOwner(uint pigId) {
        require(_piggiesContract().ownerOf(pigId) == _msgSender(), "Only owner of pig can do this.");
        _;
    }
    modifier onlyNotDead(uint pigId) {
        require(!isDead(pigId), "Pig is dead.");
        _;
    }
    modifier onlyNotOccupied(uint pigId) {
        require(_blkNumber() >= _occupiedUntil[pigId].occupiedUntil);
        _;
    }

    function _piggiesContract() private view returns(IERC721) {
        return _getERC721Token();
    }
    function _coinkContract() private view returns(IERC20) {
        return _getERC20Token();
    }
    function _attributeManagerContract() private view returns(AttributeManager) {
        return _attributeManager;
    }
    
    function distributeExcessCoink() public {
        _distributeFee(_coinkContract().balanceOf(address(this)));

        
    }
}
